//! The configuration reference page, generated from the settings: every
//! key with its type, default, what a project may do with it, and when a
//! change takes effect.

use super::{KeyInfo, Kind, keys};

/// The reference page as Markdown, ending with a newline. The same input
/// always gives the same bytes.
#[must_use]
pub fn reference_page() -> String {
    let keys = keys();
    let mut page = String::from(
        "# Configuration reference\n\
         \n\
         <!-- Generated by `cargo xtask gen` from the settings declared in \
         `crates/cortex-config/src/schema/sections.rs`. Do not edit: change the declaration and \
         regenerate. -->\n\
         \n\
         Every key a Cortex-Harness configuration file may hold. The design is in \
         [architecture/08-configuration.md](../architecture/08-configuration.md): layers, merge \
         rules, profiles, reloading and the trust rules. A JSON Schema of the same keys, for \
         editors, is in [schema.json](schema.json).\n\
         \n\
         **How to read the tables.**\n\
         \n\
         - **Type.** A length of time is text such as `\"20s\"`, `\"10m\"` or `\"1h30m\"` (units \
         `ms`, `s`, `m`, `h`, `d`). A list marked *joined* is added to by every layer; any other \
         list, like any other value, is replaced by a higher layer.\n\
         - **From a project.** What happens to the key in a project's `.cortex/config.toml` or \
         `.cortex/config.local.toml`. *preference*: applied always. *runs code* and *widens \
         access*: applied only after the user has trusted the project, and listed for the user \
         until then. *user only*: ignored, with a warning. A few keys depend on the value, and \
         say how.\n\
         - **Takes effect.** When a change to the key reaches a running harness: *at once*, at \
         the *next epoch* (it shapes the prompt, the tool list or the model), or after a \
         *restart*.\n\
         - **Enforced.** In `[permissions]`, `[sandbox]` and `[limits]` an unknown key or value \
         is an error and the file is refused: a restriction this version does not understand is \
         never skipped. Everywhere else an unknown key is a warning.\n",
    );

    // A table per section. The keys of the file itself, which have no
    // section, share the first one.
    let mut current = None;
    for key in keys.iter().filter(|key| key.kind.is_some()) {
        let section = key.path.split_once('.').map(|(section, _)| section);
        if current != Some(section) {
            current = Some(section);
            let heading = match section {
                Some(section) => format!("`[{section}]`"),
                None => "Top level".to_owned(),
            };
            page.push_str(&format!(
                "\n## {heading}\n\n\
                 | Key | Type | Default | From a project | Takes effect | What it is |\n\
                 |---|---|---|---|---|---|\n"
            ));
        }
        page.push_str(&row(key));
    }

    page.push_str(
        "\n## Reserved sections\n\
         \n\
         These sections belong to parts of the harness that are not built yet. A file may \
         already hold them: what is in them is kept and not checked. The build step that owns a \
         section declares its keys, and they then move into the tables above. Until then a \
         project's file cannot set anything in a section marked *user only*, and a section marked \
         *runs code* waits for trust.\n\
         \n\
         | Section | From a project | What it will hold |\n\
         |---|---|---|\n",
    );
    for key in keys.iter().filter(|key| key.kind.is_none()) {
        let section = key.path.trim_end_matches(".*");
        page.push_str(&format!(
            "| `[{section}]` | {} | {} |\n",
            key.trust.describe(),
            cell(&key.doc)
        ));
    }
    page
}

fn row(key: &KeyInfo) -> String {
    let kind = key.kind.as_ref().map(describe).unwrap_or_default();
    let range = key
        .range
        .map(|(low, high)| format!(", {} to {}", plain(low), plain(high)))
        .unwrap_or_default();
    let joined = if key.joined { ", joined" } else { "" };
    let enforced = if key.enforced { " Enforced." } else { "" };
    let default = match &key.default {
        Some(value) => format!("`{}`", cell(&value.to_string())),
        None => "not set".to_owned(),
    };
    format!(
        "| `{}` | {kind}{range}{joined} | {default} | {} | {} | {}{enforced} |\n",
        key.path,
        key.trust.describe(),
        key.effect.map(|effect| effect.as_str()).unwrap_or_default(),
        cell(&key.doc),
    )
}

fn describe(kind: &Kind) -> String {
    match kind {
        Kind::Bool => "`true` or `false`".to_owned(),
        Kind::Integer => "whole number".to_owned(),
        Kind::Number => "number".to_owned(),
        Kind::Text => "text".to_owned(),
        Kind::Choice(words) => words
            .iter()
            .map(|word| format!("`\"{word}\"`"))
            .collect::<Vec<_>>()
            .join(", "),
        Kind::Duration => "length of time".to_owned(),
        Kind::EnvText => "text, or `{ env = \"NAME\" }`".to_owned(),
        Kind::List(item) => format!("list of {}", describe(item)),
        Kind::Map(item) => format!("table of {}", describe(item)),
        Kind::Rule => "rule: `effect`, `match`, `action`".to_owned(),
    }
}

/// A number without a trailing `.0`.
fn plain(value: f64) -> String {
    if value.fract() == 0.0 && value.abs() < 9.0e15 {
        format!("{}", value as i64)
    } else {
        value.to_string()
    }
}

/// Text made safe for a table cell.
fn cell(text: &str) -> String {
    text.replace('|', "\\|").replace('\n', " ")
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_setting_and_every_reserved_section_has_a_row() {
        let page = reference_page();
        for key in keys() {
            match key.kind {
                Some(_) => assert!(
                    page.contains(&format!("| `{}` |", key.path)),
                    "no row for {}",
                    key.path
                ),
                None => assert!(
                    page.contains(&format!("| `[{}]` |", key.path.trim_end_matches(".*"))),
                    "no row for the reserved section {}",
                    key.path
                ),
            }
        }
        assert_eq!(page.matches("\n## Top level\n").count(), 1);
        assert_eq!(page.matches("\n## `[model]`\n").count(), 1);
        assert_eq!(page.matches("\n## Reserved sections\n").count(), 1);
    }

    #[test]
    fn a_row_says_everything_about_its_key() {
        let page = reference_page();
        let line = |key: &str| {
            page.lines()
                .find(|line| line.starts_with(&format!("| `{key}` |")))
                .unwrap_or_else(|| panic!("no row for {key}"))
                .to_owned()
        };
        assert_eq!(
            line("retry.attempts"),
            "| `retry.attempts` | whole number, 1 to 20 | `5` | preference | at once | The most \
             attempts for one request, the first included. |"
        );
        let rules = line("permissions.rules");
        assert!(
            rules.contains("list of rule: `effect`, `match`, `action`, joined"),
            "{rules}"
        );
        assert!(rules.ends_with("Enforced. |"), "{rules}");
        assert!(line("model.main").contains("| not set | preference | next epoch |"));
        assert!(line("providers.*.base_url").contains("| user only |"));
        assert!(line("model.speed").contains("| `\"standard\"` |"));
        assert!(line("credentials.store").contains("`\"auto\"`, `\"file\"`, `\"keychain\"`"));
    }

    #[test]
    fn the_same_page_comes_out_every_time() {
        let first = reference_page();
        assert_eq!(first, reference_page());
        assert!(first.ends_with("|\n"));
        assert!(!first.contains('\r'));
        assert_eq!(plain(20.0), "20");
        assert_eq!(plain(0.5), "0.5");
        assert_eq!(cell("a|b\nc"), "a\\|b c");
    }
}
